+}));
+
+test('order-list failures and count mismatches never report ok', async () => {
+  let listRequests = 0;
+  const elements = await createBrowserHarness(async (url) => {
+    if (url === '/api/orders') return browserResponse(201, { order: browserOrder, replayed: false });
+    listRequests += 1;
