+  assert.notEqual(elements.get('#result-banner').dataset.state, 'ok');
+  assert.match(elements.get('#result-detail').textContent, /의도한 주문 1건 \/ 실제 생성 0건/);
+  assert.match(elements.get('#feedback').textContent, /주문 수가 일치하지 않습니다/);
